/* ============================================================
   Tucano: tudo sobre este animal fica nesta pasta.
   Seções: 1) dados e card · 2) ícone · 3) modelo 3D · 4) comportamento

   Modelo 3D realista: "Toco Toucan Bird 3D Model Free"
   por iRahulRajput (https://sketchfab.com/rt699448), licença CC-BY-4.0
   https://sketchfab.com/3d-models/toco-toucan-bird-3d-model-free-384e7f893a1d4148b2ced5cb184956b3
   (malha reduzida de ~420 mil para ~30 mil triângulos; as cores das penas foram
   gravadas nos vértices; as asas foram separadas do corpo para bater de verdade)
   ============================================================ */

/* --- Dados do modelo 3D embutidos (NÃO EDITAR; sem arquivos externos, funciona abrindo direto o index.html) --- */
const TUCANO_MESH = {"body":{"n":7894,"pos":"","nrm":"","col":"","idx":""},"wl":{"n":3383,"pos":"","nrm":"","col":"","idx":""},"wr":{"n":3364,"pos":"","nrm":"","col":"","idx":""},"pivot":[-0.19640627652153778,-0.053244276729388675,0.16],"len":1.8963574767112732,"minY":-0.7767892458609172,"cx":-0.0018552839756011963,"feetY":-0.5443063506893083};

registerAnimal('tucano', {

  /* 1) DADOS: card informativo, quantidade inicial/máxima, cor do destaque e área de clique */
  data: {
      name: "Tucano",
      sci: "Ramphastos toco",
      diet: "Frugívoro",
      role: "Dispersor de sementes",
      habitat: "Copas das árvores e bordas de floresta.",
      desc: "Ave de grande bico colorido que engole frutos inteiros e espalha as sementes por onde voa.",
      fact: "O bico é leve e ajuda a controlar a temperatura do corpo da ave.",
      qty: 7,
      max: 24,
      color: "#42a5f5",
      hit: 0.9,
      hy: 0,
      top: 1.1,
      kind: "fly"
  },

  /* 2) ÍCONE (legenda e card) */
  icon: `<svg viewBox="0 0 48 48" aria-hidden="true"><ellipse cx="18" cy="28" rx="11" ry="14" fill="#1a1a22"/><path d="M12 36l-4 9 8-4z" fill="#1a1a22"/><circle cx="21" cy="14" r="8" fill="#1a1a22"/><ellipse cx="22" cy="21" rx="6" ry="5" fill="#fff"/><path d="M26 10c10-1 19 3 20 8-1 4-10 6-20 4z" fill="#ff8c00"/><path d="M26 17c8 1 15 0 19 0-3 3-11 5-19 3z" fill="#ffd23f"/><circle cx="22" cy="12" r="2.4" fill="#fff"/><circle cx="22.6" cy="12" r="1.1" fill="#111"/><path d="M13 36c2 5 7 5 9 5" stroke="#d64045" stroke-width="2.4" fill="none"/></svg>`,

  /* 3) MODELO 3D: corpo + duas asas articuladas no ombro.
        Voando: as asas batem seguindo o sinal de bater de asas do sistema.
        Pousado (sinal parado): as asas relaxam, caídas e um pouco para trás. */
  build(sp) {
    const { M } = Kit, u = sp.top, g = new THREE.Group(), rig = new THREE.Group(); g.add(rig);
    const sh = tucanoShared(), D = TUCANO_MESH;

    const model = new THREE.Group(), s = 2.2 * u / D.len;           // comprimento bico-cauda ≈ 2,2u (como antes)
    model.scale.setScalar(s);
    model.position.set(-D.cx * s, -u * .4 - D.feetY * s, 0);         // patas na mesma altura de antes
    rig.add(model);

    const bodyMesh = new THREE.Mesh(sh.body, sh.mat); bodyMesh.castShadow = true; model.add(bodyMesh);
    const mkWing = (geo, side) => {
      const pv = new THREE.Group(); pv.position.set(D.pivot[0], D.pivot[1], D.pivot[2] * side);
      const m = new THREE.Mesh(geo, sh.mat); m.castShadow = true; m.frustumCulled = false; pv.add(m); model.add(pv); return pv;
    };
    const pL = mkWing(sh.wl, 1), pR = mkWing(sh.wr, -1);

    // pivôs de asa do sistema (invisíveis): fornecem o sinal de bater de asas
    const before = rig.children.length;
    const wings = Kit.wings(rig, u, 0x1a1a22);
    for (let i = before; i < rig.children.length; i++) rig.children[i].visible = false;

    const st = { t: Math.random() * 6, e: 1 };
    const clamp = (v, a, b) => Math.max(a, Math.min(b, v)), lerp = (a, b, k) => a + (b - a) * k;
    bodyMesh.onBeforeRender = () => {
      // O sistema move a asa em rotation.x: bate entre -0,7 e +0,7 voando e fica em +1,3 com a asa dobrada (pousado).
      const w = Array.isArray(wings) && wings[0], p = w && (Array.isArray(w) ? w[0] : w);
      let sn, e;
      if (p && p.rotation) {
        const v = p.rotation.x;
        sn = clamp(v / .7, -1, 1);                    // fase da batida [-1, 1]
        e = 1 - clamp((v - .75) / .5, 0, 1);          // 1 = voando, 0 = pousado (asas dobradas)
      } else { st.t += .016; sn = Math.sin(st.t * 10); e = 1; }   // não achou o sinal do sistema: bate sozinho
      e = st.e += (e - st.e) * .3;                    // transição suave entre voar e pousar
      const d = lerp(-1.4, -.375 + .625 * sn, e);     // elevação da asa (rad): repouso -> batida
      const sweep = (1 - e) * .6;                     // asas levemente para trás no repouso
      pL.rotation.set(-d, -sweep, 0); pR.rotation.set(d, sweep, 0);
      pL.scale.z = pR.scale.z = lerp(.85, 1, e);
    };

    g.userData = { wings, head: bodyMesh, rig };
    return g;
  },

  /* 4) COMPORTAMENTO: voa e pousa no topo das árvores. */
  decide(a, H) {
    if (Math.random() < .4) { const t = H.rt(); return H.go(a, H.V(t.x, t.top + .3, t.z), 'land', H.r(5, 10)); }
    H.go(a, H.flyPoint('tucano'), 'fly', 0);
  }
});

/* Geometrias e material compartilhados por todos os tucanos (criados uma única vez). */
let _tucanoShared = null;
function tucanoShared() {
  if (_tucanoShared) return _tucanoShared;
  const D = TUCANO_MESH;
  const bytes = b64 => { const s = atob(b64), a = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) a[i] = s.charCodeAt(i); return a; };
  const lin = new Float32Array(256); for (let i = 0; i < 256; i++) lin[i] = Math.pow(i / 255, 2.2);   // sRGB -> linear
  const make = P => {
    const n = P.n, i16 = new Int16Array(bytes(P.pos).buffer), i8 = new Int8Array(bytes(P.nrm).buffer), c8 = bytes(P.col), idx = new Uint16Array(bytes(P.idx).buffer);
    const pos = new Float32Array(n * 3), nrm = new Float32Array(n * 3), col = new Float32Array(n * 3);
    for (let i = 0; i < n * 3; i++) { pos[i] = i16[i] / 32000; nrm[i] = i8[i] / 127; col[i] = lin[c8[i]]; }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('normal', new THREE.BufferAttribute(nrm, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    geo.setIndex(new THREE.BufferAttribute(idx, 1));
    geo.computeBoundingSphere();
    return geo;
  };
  const mat = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: .75, metalness: 0, side: THREE.DoubleSide });
  return (_tucanoShared = { body: make(D.body), wl: make(D.wl), wr: make(D.wr), mat });
}
